1	'use server';
2	
3	import { createSupabaseAdminClient } from "@/lib/supabase/server";
4	import { fetchMemberNickname } from "@/lib/name-api";
5	
6	type UserWithDetails = {
7	    id: string;
8	    display_name: string;
9	    card_id: string | null;
10	    team_name: string | null;
11	    team_id: string | null;
12	    generation: number;
13	    is_admin: boolean;
14	    latest_attendance_type: string | null;
15	    latest_timestamp: string | null;
16	    deleted_at: string | null;
17	    student_number: string | null;
18	    status: number;
19	};
20	
21	/**
22	 * すべてのユーザー情報を取得（管理画面用）
23	 */
24	export async function getAllUsersWithStatus(): Promise<{ data: UserWithDetails[], error: any }> {
25	    const supabase = await createSupabaseAdminClient();
26	
27	    try {
28	        // member.membersからユーザー情報を取得
29	        const { data: members, error: membersError } = await supabase
30	            .schema('member')
31	            .from('members')
32	            .select(`
33	                supabase_auth_user_id,
34	                discord_uid,
35	                generation,
36	                is_admin,
37	                student_number,
38	                status,
39	                deleted_at,
40	                member_team_relations(team_id, teams(name))
41	            `);
42	
43	        if (membersError) {
44	            console.error('Error fetching members:', membersError);
45	            return { data: [], error: membersError };
46	        }
47	
48	        // attendance.usersからカード情報を取得
49	        const { data: attendanceUsers } = await supabase
50	            .schema('attendance')
51	            .from('users')
52	            .select('supabase_auth_user_id, card_id');
53	
54	        const cardMap = new Map(attendanceUsers?.map(u => [u.supabase_auth_user_id, u.card_id]) || []);
55	
56	        // 最新の打刻情報を取得
57	        const memberIds = members?.map((m: any) => m.supabase_auth_user_id) || [];
58	        const { data: latestAttendances } = await supabase
59	            .schema('attendance')
60	            .from('attendances')
61	            .select('user_id, type, timestamp')
62	            .in('user_id', memberIds)
63	            .order('timestamp', { ascending: false });
64	
65	        // 各ユーザーの最新打刻を抽出
66	        const latestAttendanceMap = new Map<string, { type: string; timestamp: string }>();
67	        latestAttendances?.forEach((att: any) => {
68	            if (!latestAttendanceMap.has(att.user_id)) {
69	                latestAttendanceMap.set(att.user_id, { type: att.type, timestamp: att.timestamp });
70	            }
71	        });
72	
73	        // Discord UIDから本名を一括取得（エラー耐性を持たせる）
74	        const discordUids = members?.map((m: any) => m.discord_uid).filter(Boolean) || [];
75	        const nameMap = new Map<string, string>();
76	        
77	        // 本名取得API呼び出し（エラーが発生しても続行）
78	        await Promise.allSettled(
79	            discordUids.map(async (discord_uid: string) => {
80	                try {
81	                    const { data: nickname, error } = await fetchMemberNickname(discord_uid);
82	                    if (nickname && !error) {
83	                        nameMap.set(discord_uid, nickname);
84	                    }
85	                } catch (error) {
86	                    // 個別のエラーは無視して続行
87	                    console.warn(`Failed to fetch nickname for ${discord_uid}:`, error);
88	                }
89	            })
90	        );
91	
92	        // データを結合
93	        const users = members?.map((member: any) => {
94	            const latestAttendance = latestAttendanceMap.get(member.supabase_auth_user_id);
95	            const teamRelation = member.member_team_relations?.[0];
96	            const realName = member.discord_uid ? nameMap.get(member.discord_uid) : null;
97	            
98	            return {
99	                id: member.supabase_auth_user_id,
100	                display_name: realName || '名無しさん',
101	                card_id: cardMap.get(member.supabase_auth_user_id) || null,
102	                team_name: teamRelation?.teams?.name || null,
103	                team_id: teamRelation?.team_id || null,
104	                generation: member.generation,
105	                is_admin: member.is_admin,
106	                latest_attendance_type: latestAttendance?.type || null,
107	                latest_timestamp: latestAttendance?.timestamp || null,
108	                deleted_at: member.deleted_at,
109	                student_number: member.student_number,
110	                status: member.status ?? 0, // 0: 中学生, 1: 高校生, 2: OB/OG
111	            };
112	        }) || [];
113	
114	        return { data: users, error: null };
115	    } catch (error) {
116	        console.error('Error in getAllUsersWithStatus:', error);
117	        return { data: [], error };
118	    }
119	}
120	
121	/**
122	 * ユーザーの表示名を更新
123	 */
124	export async function updateUserDisplayName(userId: string, displayName: string) {
125	    const supabase = await createSupabaseAdminClient();
126	    
127	    const { error } = await supabase
128	        .schema('member')
129	        .from('members')
130	        .update({ display_name: displayName })
131	        .eq('supabase_auth_user_id', userId);
132	    
133	    return { success: !error, error };
134	}
135	
136	/**
137	 * 全ユーザーの表示名を一括更新
138	 */
139	export async function updateAllUserDisplayNames() {
140	    const supabase = await createSupabaseAdminClient();
141	
142	    try {
143	        const { data: members, error: fetchError } = await supabase
144	            .schema('member')
145	            .from('members')
146	            .select('supabase_auth_user_id, discord_uid');
147	
148	        if (fetchError || !members) {
149	            return { success: false, message: 'ユーザーの取得に失敗しました。' };
150	        }
151	
152	        let successCount = 0;
153	        let failCount = 0;
154	
155	        // 並列処理で全ユーザーの名前を更新（エラー耐性）
156	        await Promise.allSettled(
157	            members.map(async (member: any) => {
158	                if (!member.discord_uid) return;
159	
160	                try {
161	                    const { data: nickname, error } = await fetchMemberNickname(member.discord_uid);
162	                    
163	                    if (nickname && !error) {
164	                        const { error: updateError } = await supabase
165	                            .schema('member')
166	                            .from('members')
167	                            .update({ display_name: nickname })
168	                            .eq('supabase_auth_user_id', member.supabase_auth_user_id);
169	
170	                        if (!updateError) {
171	                            successCount++;
172	                        } else {
173	                            failCount++;
174	                        }
175	                    } else {
176	                        failCount++;
177	                    }
178	                } catch {
179	                    failCount++;
180	                }
181	            })
182	        );
183	
184	        return {
185	            success: true,
186	            message: `更新完了: 成功 ${successCount}件、失敗 ${failCount}件`,
187	        };
188	    } catch (error) {
189	        console.error('Error updating all display names:', error);
190	        return { success: false, message: '更新中にエラーが発生しました。' };
191	    }
192	}
193	
194	/**
195	 * ユーザーのカードIDを更新
196	 */
197	export async function updateUserCardId(userId: string, newCardId: string) {
198	    const supabase = await createSupabaseAdminClient();
199	
200	    try {
201	        // カードIDを正規化（コロンを削除、小文字化）
